CREATE OR REPLACE FUNCTION public.award_challenge_exp(_user_id bigint, _challenge_id bigint, _multiplier numeric DEFAULT 1, _metadata jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(created boolean, awarded integer, exp_after bigint, previous_level integer, new_level integer)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_rule varchar;
BEGIN
    SELECT CASE WHEN ch.type = 'quiz' THEN 'quiz.' || ch.difficulty
                ELSE 'coding.' || ch.type || '.' || ch.difficulty END
    INTO v_rule
    FROM challenge.challenges ch
    WHERE ch.id = _challenge_id;

    RETURN QUERY SELECT * FROM public.award_exp(_user_id, v_rule, 'challenge', _challenge_id, _multiplier, _metadata);
END;
